<?php
namespace OpenLMS\Controllers;

use OpenLMS\Core\Auth;
use OpenLMS\Core\Csrf;
use OpenLMS\Core\Database;
use OpenLMS\Policies\CoursePolicy;
use PDO;

trait AssessmentQuizTrait
{
    public static function quizzes(): void
    {
        require_feature('quizzes');Auth::requirePermission('exams.manage');$user=Auth::user();$pdo=Database::connection();$error=null;$message=null;
        if($_SERVER['REQUEST_METHOD']==='POST'){
            if(!Csrf::validate($_POST['_csrf']??null))$error='Security token expired.';else try{$action=(string)($_POST['action']??'');
                if($action==='create'){$courseId=(int)($_POST['course_id']??0);$course=self::course($courseId);if(!$course||!CoursePolicy::canManage($course,$user))throw new \RuntimeException('Course access denied.');$title=trim((string)($_POST['title']??''));if($title==='')throw new \RuntimeException('Title is required.');$duration=max(1,(int)($_POST['duration_minutes']??30));$pass=max(0,(float)($_POST['pass_marks']??0));$attempts=max(1,(int)($_POST['attempt_limit']??1));$start=utc_datetime_from_input($_POST['starts_at']??null);$end=utc_datetime_from_input($_POST['ends_at']??null);if($start&&$end&&$end<=$start)throw new \RuntimeException('End time must be after start time.');$now=gmdate('Y-m-d H:i:s');$pdo->prepare("INSERT INTO quizzes (course_id,title,duration_minutes,total_marks,pass_marks,attempt_limit,starts_at,ends_at,status,created_at,assessment_type,negative_marking,randomize_questions,shuffle_options,review_policy,result_publication,instructions,updated_at) VALUES (?,?,?,0,?,?,?,?,?,?,?,?,?,?,?,?,?,?)")->execute([$courseId,$title,$duration,$pass,$attempts,$start,$end,'draft',$now,'quiz',max(0,(float)($_POST['negative_marking']??0)),bool_post('randomize_questions'),bool_post('shuffle_options'),(string)($_POST['review_policy']??'after_submit'),(string)($_POST['result_publication']??'immediate'),trim((string)($_POST['instructions']??'')),$now]);$message='Quiz created.';
                }elseif($action==='attach'){$quizId=(int)($_POST['quiz_id']??0);$quiz=self::quiz($quizId);if(!$quiz||!self::canManageQuiz($quiz,$user))throw new \RuntimeException('Quiz access denied.');$qid=(int)($_POST['question_id']??0);$q=self::question($qid);if(!$q||(int)$q['course_id']!==(int)$quiz['course_id'])throw new \RuntimeException('Question must belong to the same course.');$st=$pdo->prepare('SELECT COUNT(*) FROM quiz_questions WHERE quiz_id=? AND question_id=?');$st->execute([$quizId,$qid]);if(!(int)$st->fetchColumn()){$order=(int)$pdo->query('SELECT COALESCE(MAX(sort_order),0)+1 FROM quiz_questions WHERE quiz_id='.(int)$quizId)->fetchColumn();$pdo->prepare('INSERT INTO quiz_questions (quiz_id,question_id,sort_order) VALUES (?,?,?)')->execute([$quizId,$qid,$order]);}self::recalcQuiz($quizId);$message='Question attached.';
                }elseif($action==='detach'){$quizId=(int)($_POST['quiz_id']??0);$quiz=self::quiz($quizId);if(!$quiz||!self::canManageQuiz($quiz,$user))throw new \RuntimeException('Quiz access denied.');$pdo->prepare('DELETE FROM quiz_questions WHERE quiz_id=? AND question_id=?')->execute([$quizId,(int)($_POST['question_id']??0)]);self::recalcQuiz($quizId);$message='Question removed.';
                }elseif($action==='status'){$quizId=(int)($_POST['quiz_id']??0);$quiz=self::quiz($quizId);if(!$quiz||!self::canManageQuiz($quiz,$user))throw new \RuntimeException('Quiz access denied.');$status=(string)($_POST['status']??'draft');if(!in_array($status,['draft','published','archived'],true))throw new \RuntimeException('Invalid status.');if($status==='published'&&(int)$quiz['question_count']<1)throw new \RuntimeException('Add at least one question before publishing.');$pdo->prepare('UPDATE quizzes SET status=?,updated_at=? WHERE id=?')->execute([$status,gmdate('Y-m-d H:i:s'),$quizId]);$message='Quiz status updated.';}
            }catch(\Throwable $e){$error=$e instanceof \RuntimeException?$e->getMessage():'Unable to update quiz.';}}
        $courses=self::manageableCourses($user);$quizzes=self::quizRows($user);$selected=(int)($_GET['quiz_id']??($quizzes[0]['id']??0));$attached=[];$available=[];if($selected){$quiz=self::quiz($selected);if($quiz&&self::canManageQuiz($quiz,$user)){$st=$pdo->prepare('SELECT q.*,qq.sort_order FROM quiz_questions qq JOIN questions q ON q.id=qq.question_id WHERE qq.quiz_id=? ORDER BY qq.sort_order');$st->execute([$selected]);$attached=$st->fetchAll();$st=$pdo->prepare('SELECT q.*,qb.name bank_name FROM questions q JOIN question_banks qb ON qb.id=q.question_bank_id WHERE qb.course_id=? ORDER BY q.id DESC');$st->execute([(int)$quiz['course_id']]);$available=$st->fetchAll();}}
        ob_start();?><div class="page-head"><div><h1>Quizzes</h1><p class="muted">Configure duration, marks, negative marking, attempts, randomization, review and publication.</p></div><a class="btn" href="<?=e(app_url('?r=assessment-review'))?>">Review attempts</a></div><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?>
        <div class="grid-2"><section class="card"><h2>Create quiz</h2><p class="hint">Start and end times use the LMS timezone: <?=e(app_timezone())?>.</p><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="create"><label>Course<select name="course_id" required><?php foreach($courses as $c):?><option value="<?=(int)$c['id']?>"><?=e($c['title'])?></option><?php endforeach;?></select></label><label>Title<input name="title" required></label><div class="form-row"><label>Duration (minutes)<input type="number" name="duration_minutes" min="1" value="30"></label><label>Pass marks<input type="number" name="pass_marks" min="0" step="0.25" value="0"></label></div><div class="form-row"><label>Attempt limit<input type="number" name="attempt_limit" min="1" value="1"></label><label>Negative mark / wrong objective answer<input type="number" name="negative_marking" min="0" step="0.25" value="0"></label></div><div class="form-row"><label>Starts<input type="datetime-local" name="starts_at"></label><label>Ends<input type="datetime-local" name="ends_at"></label></div><label class="check-row"><input type="checkbox" name="randomize_questions" value="1"> Randomize questions per attempt</label><label class="check-row"><input type="checkbox" name="shuffle_options" value="1"> Shuffle options per attempt</label><label>Review policy<select name="review_policy"><option value="after_submit">After submission</option><option value="after_close">After assessment closes</option><option value="never">Never show answers</option></select></label><label>Result publication<select name="result_publication"><option value="immediate">Immediate after grading</option><option value="manual">Manual / teacher controlled</option></select></label><label>Instructions<textarea name="instructions"></textarea></label><button class="btn btn-primary">Create quiz</button></form></section>
        <section class="card"><h2>Existing quizzes</h2><div class="compact-list"><?php foreach($quizzes as $q):?><a href="<?=e(app_url('?r=quizzes&quiz_id='.(int)$q['id']))?>"><span><strong><?=e($q['title'])?></strong><small><?=e($q['course_title'])?> · <?=e($q['status'])?></small></span><span class="badge"><?=e($q['total_marks'])?> marks · <?=(int)$q['question_count']?> Q</span></a><?php endforeach;?></div></section></div>
        <?php if($selected&&isset($quiz)):?><div class="grid-2"><section class="card"><h2>Attached questions</h2><div class="compact-list"><?php foreach($attached as $q):?><div><span><strong><?=e(mb_strimwidth($q['prompt'],0,80,'…'))?></strong><small><?=e($q['type'])?> · <?=e($q['marks'])?> marks</small></span><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="detach"><input type="hidden" name="quiz_id" value="<?=$selected?>"><input type="hidden" name="question_id" value="<?=(int)$q['id']?>"><button class="btn btn-small">Remove</button></form></div><?php endforeach;?></div></section><section class="card"><h2>Add from course question banks</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="attach"><input type="hidden" name="quiz_id" value="<?=$selected?>"><label>Question<select name="question_id"><?php foreach($available as $q):?><option value="<?=(int)$q['id']?>"><?=e($q['bank_name'].' · '.mb_strimwidth($q['prompt'],0,80,'…'))?></option><?php endforeach;?></select></label><button class="btn">Attach question</button></form><hr><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="quiz_id" value="<?=$selected?>"><label>Status<select name="status"><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></label><button class="btn btn-primary">Update status</button></form></section></div><?php endif;?>
        <?php render_page('Quizzes',ob_get_clean());
    }
    public static function gradebook(): void
    {
        require_feature('gradebook');Auth::requireAuth();$u=Auth::user();$pdo=Database::connection();
        if(in_array('student',$u['roles'],true)&&!Auth::can('reports.view')){$st=$pdo->prepare('SELECT g.*,c.title course_title FROM grades g JOIN courses c ON c.id=g.course_id WHERE g.user_id=? ORDER BY g.graded_at DESC');$st->execute([(int)$u['id']]);$rows=$st->fetchAll();}
        else{Auth::requirePermission('reports.view');$where=Auth::hasAnyRole(['super_admin','administrator','hod'])?'1=1':'c.teacher_id=?';$st=$pdo->prepare("SELECT g.*,c.title course_title,u.name student_name,u.email FROM grades g JOIN courses c ON c.id=g.course_id JOIN users u ON u.id=g.user_id WHERE $where ORDER BY g.graded_at DESC LIMIT 300");$st->execute($where==='1=1'?[]:[(int)$u['id']]);$rows=$st->fetchAll();}
        ob_start();?><div class="page-head"><div><h1>Gradebook</h1><p class="muted">Published assessment and project grades.</p></div></div><section class="card table-card"><div class="table-scroll"><table><thead><tr><?php if(!in_array('student',$u['roles'],true)||Auth::can('reports.view')):?><th>Student</th><?php endif;?><th>Course</th><th>Item</th><th>Score</th><th>Graded</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php if(!in_array('student',$u['roles'],true)||Auth::can('reports.view')):?><td><?=e($r['student_name']??'')?><small><?=e($r['email']??'')?></small></td><?php endif;?><td><?=e($r['course_title'])?></td><td><?=e($r['item_type'].' #'.$r['item_id'])?></td><td><?=e($r['marks']??'—')?> / <?=e($r['max_marks']??'—')?></td><td><?=e($r['graded_at']??'Pending')?></td></tr><?php endforeach;?></tbody></table></div></section><?php render_page('Gradebook',ob_get_clean());
    }
}
